// medium (default, 36px) and small (32px).
<Input size="medium" label="Email" placeholder="Enter your email" /* … */ />
<Input size="small" label="Email" placeholder="Enter your email" /* … */ />

// Hover / focus cross-fade the ring automatically. isDisabled and
// isInvalid override them and repaint the field, hint and label.
<Input label="Email" placeholder="Enter your email" /* default */ />
<Input label="Email" value="hello@example.com" /* filled */ />
<Input label="Email" placeholder="Enter your email" isDisabled />
<Input label="Email" value="not-a-real-email" isInvalid />

import * as Flags from "country-flag-icons/react/3x2";
import { getCountryDataList } from "countries-list";
import { Select, SelectItem } from "@/components/base/select/select";

// Real ISO countries that ship a flag + a dial code, sorted by name.
const COUNTRIES = getCountryDataList()
  .filter((c) => Flags[c.iso2] && c.phone.length > 0)
  .map((c) => ({ iso2: c.iso2, name: c.name, dial: c.phone[0] }))
  .sort((a, b) => a.name.localeCompare(b.name));

// The country-code Select goes in the input's leading addon slot.
<Input
  label="Phone Number"
  placeholder="(123) 000-0000"
  leadingAddon={<CountryCodeSelect />}
  trailingIcon={RiQuestionLine}
/>

function CountryCodeSelect() {
  const [iso2, setIso2] = useState("US");
  const dial = COUNTRIES.find((c) => c.iso2 === iso2)?.dial;
  return (
    <Select
      aria-label="Country code"
      selectedKey={iso2}
      onSelectionChange={(key) => setIso2(String(key))}
      triggerClassName="rounded-lg px-1.5 py-1"
      popoverClassName="w-[220px]"
      renderValue={() => <><Flag iso2={iso2} /> +{dial}</>}
    >
      {COUNTRIES.map((c) => (
        <SelectItem key={c.iso2} id={c.iso2} textValue={c.name}>
          <Flag iso2={c.iso2} />
          <span className="flex-1 truncate">{c.name}</span>
          <span className="text-text-tertiary">+{c.dial}</span>
        </SelectItem>
      ))}
    </Select>
  );
}
